import * as THREE from 'three';
import {materials} from '../../core/index.js';
import {mesh,FACE,portQuaternion} from '../../modeling/parts.js';
import {roundedRect} from '../../core/geometry.js';
export {THREE,materials,FACE,portQuaternion,roundedRect};
export const box=(p,s,at,m,n)=>mesh(p,new THREE.BoxGeometry(...s),m,at,n);
export function polygon(points){const s=new THREE.Shape();points.forEach(([x,y],i)=>i?s.lineTo(x,y):s.moveTo(x,y));s.closePath();return s;}
export function hole(s,x,y,r){const h=new THREE.Path();h.absarc(x,y,r,0,Math.PI*2,false);s.holes.push(h);return s;}
export function solid(parent,input,depth,position,material,name){const raw=input.extractPoints(40),outer=THREE.ShapeUtils.isClockWise(raw.shape)?raw.shape:raw.shape.reverse(),s=polygon(outer.map(v=>[v.x,v.y]));for(const path of raw.holes){const h=THREE.ShapeUtils.isClockWise(path)?path.reverse():path;s.holes.push(polygon(h.map(v=>[v.x,v.y])));}return mesh(parent,new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:false,curveSegments:40}),material,position,name);}
export function ring(p,r,inner,d,at,m,n){const s=new THREE.Shape();s.absarc(0,0,r,0,Math.PI*2,false);hole(s,0,0,inner);return solid(p,s,d,at,m,n);}
export const cylinder=(p,r,d,at,m,n)=>mesh(p,new THREE.CylinderGeometry(r,r,d,64).rotateX(Math.PI/2),m,at,n);
/** Own R1 external rolled edge only;bores retain their actual Ø5 cylindrical walls. */
export function rolledEdge(parent,{front=true,material}){const open=front,N=20,K=12,boundary=inset=>{const a=[],r=4-inset,add=(x,y)=>a.push([x,y]);if(open)add(5.2,-24+inset);else add(8,-24+inset);if(open)add(8,-24+inset);for(const[cx,cy,start]of[[8,-20,-Math.PI/2],[8,20,0],[-8,20,Math.PI/2],[-8,-20,Math.PI]]){for(let i=0;i<=N;i++){const t=start+i/N*Math.PI/2,x=cx+r*Math.cos(t),y=cy+r*Math.sin(t);if(a.length&&Math.hypot(x-a.at(-1)[0],y-a.at(-1)[1])<1e-8)continue;add(x,y);}}if(open)add(-5.2,-24+inset);return a;},outer=[],inner=[],points=[];for(let k=0;k<=K;k++){const t=k/K*Math.PI/2,z=3+Math.sin(t),b=boundary(1-Math.cos(t)),i=boundary(1);outer.push(b.map(([x,y])=>[x,y,z]));inner.push(i.map(([x,y])=>[x,y,z]));}const count=outer[0].length,tri=(a,b,c)=>{const v=new THREE.Vector3(...b).sub(new THREE.Vector3(...a)).cross(new THREE.Vector3(...c).sub(new THREE.Vector3(...a)));if(v.lengthSq()<1e-18)return;if(front)points.push(...a,...b,...c);else points.push(a[0],a[1],-a[2],c[0],c[1],-c[2],b[0],b[1],-b[2]);},quad=(a,b,c,d)=>{tri(a,b,c);tri(a,c,d);},segments=open?count-1:count;for(let i=0;i<segments;i++){const j=(i+1)%count;quad(outer[0][i],inner[0][i],inner[0][j],outer[0][j]);for(let k=0;k<K;k++){quad(outer[k][i],outer[k][j],outer[k+1][j],outer[k+1][i]);quad(inner[k][j],inner[k][i],inner[k+1][i],inner[k+1][j]);}}if(open)for(let k=0;k<K;k++){quad(outer[k][0],outer[k+1][0],inner[k+1][0],inner[k][0]);const i=count-1;quad(outer[k][i],inner[k][i],inner[k+1][i],outer[k+1][i]);}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(points,3));geometry.computeVertexNormals();return mesh(parent,geometry,material,[0,0,0],'Original U032 actual R1 '+(front?'front':'rear')+' external edge material');}
